#!/usr/bin/env bash
###
# install-dota2-announcer-sounds.sh
# Self-contained installer for Dota 2 Announcer sound effects for Claude Code hooks.
# All 16 .wav files are embedded (base64) — no external downloads needed.
#
# Events:
#   SessionStart      → 'Prepare for battle', 'The battle begins'
#   UserPromptSubmit  → Kill streak: 'First blood', 'Double kill', 'Triple kill', 'Ultra kill', 'Killing spree'
#   Stop              → Big kills: 'Rampage', 'Godlike', 'Holy shit', 'Ownage', 'Monster kill'
#   Notification      → Streaks: 'Dominating', 'Mega kill', 'Unstoppable', 'Wicked sick' (permission prompts only)
#
# Prerequisites:
#   - macOS (uses afplay + base64 -D)
#
# Usage: bash install-dota2-announcer-sounds.sh
###
set -euo pipefail

SOUNDS_DIR="$HOME/.claude/hooks/sounds/dota2_announcer"
mkdir -p "$SOUNDS_DIR"

echo "Extracting 16 Dota 2 Announcer sound files..."

base64 -D << 'B64EOF' > "$SOUNDS_DIR/battle_begin.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/dominating.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/double_kill.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/first_blood.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/godlike.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/holy_shit.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/killing_spree.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/mega_kill.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/monster_kill.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/ownage.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/prepare_for_battle.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/rampage.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/triple_kill.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/ultra_kill.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/unstoppable.mp3"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/wicked_sick.mp3"

B64EOF

echo ""
echo "Done! Dota 2 Announcer sounds installed to $SOUNDS_DIR"
echo "To test: afplay $SOUNDS_DIR/prepare_for_battle.mp3"
